"""Generate native sRGB roles from the maintained design data (stdlib only)."""

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "docs/design/tokens.json"
DESTINATION = ROOT / "application/crates/ox-ui/src/tokens.rs"


def render(document):
    themes = document["themes"]
    names = list(themes["light"]["roles"])
    lines = [
        "// Generated by application/tools/build_design.py; edit docs/design/tokens.json.",
        "use iced::Color;",
        "#[derive(Debug, Clone, Copy)]",
        "pub struct Palette {",
        *[f"    pub {name}: Color," for name in names],
        "}",
    ]
    for theme, definition in themes.items():
        if set(definition["roles"]) != set(names):
            raise ValueError("Theme role inventory differs: " + theme)
        lines.append(f"pub const {theme.upper()}: Palette = Palette {{")
        for name, value in definition["roles"].items():
            if len(value) != 7 or value[0] != "#":
                raise ValueError("Expected opaque sRGB HEX: " + value)
            rgb = [int(value[i:i + 2], 16) for i in (1, 3, 5)]
            lines.append(f"    {name}: Color::from_rgb8({rgb[0]}, {rgb[1]}, {rgb[2]}),")
        lines.append("};")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render(json.loads(SOURCE.read_text()))
    if args.check:
        if DESTINATION.read_text() != expected:
            raise SystemExit("Generated native roles differ from controlled tokens")
        print("Native role generation matches the controlled source")
    else:
        DESTINATION.write_text(expected)
        print("Generated", DESTINATION.relative_to(ROOT))


if __name__ == "__main__":
    main()
